from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path

import bot
from store import DEFAULT_TIMES, SECRET_KEYS, Store, now

BASE = Path(__file__).resolve().parent
DATA_DIR = Path(os.environ.get("DATA_DIR", BASE / "data"))
DATA_DIR.mkdir(parents=True, exist_ok=True)
PASSWORD = os.environ.get("APP_PASSWORD", "")
SECRET = (os.environ.get("SESSION_SECRET") or hashlib.sha256(("rp:" + PASSWORD).encode()).hexdigest()).encode()
SESSION_DAYS = 60

store = Store(DATA_DIR / "repost.db")
engine = bot.Engine(store, DATA_DIR)

# Web files are built in, so the app works even if the static/ folder wasn't uploaded
_EMBEDDED = {
    "index.html": "",
    "manifest.json": "",
    "icon.svg": "",
}


def static_file(name):
    # Always use the built-in copy so leftover files in the repo can't show an old version
    return base64.b64decode(_EMBEDDED[name])


LEGAL_STYLE = """<style>body{margin:0;background:#0e0f12;color:#e8eaf0;font:16px/1.6 -apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif}
main{max-width:720px;margin:0 auto;padding:32px 20px 60px}h1{font-size:28px;margin:0 0 4px}h2{font-size:18px;margin:28px 0 6px}
p,li{color:#c3c8d4}a{color:#25d6c4}.muted{color:#8b92a1;font-size:14px}</style>"""


